from django.utils import timezone

DEFAULT_TENANT_SLUG = "default"


def bootstrap_default_tenant(apps, schema_editor):
    """Place existing users in one default tenant with built-in roles."""

    Tenant = apps.get_model("accounts", "Tenant")
    TenantMembership = apps.get_model("accounts", "TenantMembership")
    Profile = apps.get_model("accounts", "Profile")
    Role = apps.get_model("accounts", "Role")
    User = apps.get_model("auth", "User")

    tenant, _ = Tenant.objects.get_or_create(
        slug=DEFAULT_TENANT_SLUG,
        defaults={
            "name": "Default Tenant",
            "status": "active",
        },
    )
    now = timezone.now()

    for user in User.objects.all().iterator():
        profile, _ = Profile.objects.get_or_create(user_id=user.pk)

        role_ids = set(user.platform_roles.filter(is_active=True).values_list("id", flat=True))
        for group in user.groups.all():
            role_ids.update(group.platform_roles.filter(is_active=True).values_list("id", flat=True))
        has_admin_console = any(
            "admin_console" in (features or [])
            for features in Role.objects.filter(id__in=role_ids).values_list("visible_features", flat=True)
        )

        is_platform_admin = bool(user.is_staff or user.is_superuser)
        if is_platform_admin and profile.platform_role != "super_admin":
            profile.platform_role = "super_admin"
            profile.save(update_fields=["platform_role"])

        expected_role = "tenant_admin" if is_platform_admin or has_admin_console else "member"
        membership, created = TenantMembership.objects.get_or_create(
            user_id=user.pk,
            defaults={
                "tenant": tenant,
                "role": expected_role,
                "status": "active",
                "joined_at": user.date_joined or now,
            },
        )
        if created:
            continue

        update_fields = []
        if membership.tenant_id != tenant.pk:
            membership.tenant = tenant
            update_fields.append("tenant")
        if membership.role != expected_role:
            membership.role = expected_role
            update_fields.append("role")
        if membership.status != "active":
            membership.status = "active"
            update_fields.append("status")
        if membership.joined_at is None:
            membership.joined_at = user.date_joined or now
            update_fields.append("joined_at")
        if update_fields:
            membership.save(update_fields=update_fields)


def backfill_tenant_groups(apps, schema_editor):
    """Attach existing Django groups to the bootstrap tenant."""

    Tenant = apps.get_model("accounts", "Tenant")
    TenantGroup = apps.get_model("accounts", "TenantGroup")
    Group = apps.get_model("auth", "Group")

    tenant = Tenant.objects.filter(slug=DEFAULT_TENANT_SLUG).first()
    if tenant is None:
        return

    for group in Group.objects.all().iterator():
        TenantGroup.objects.get_or_create(
            auth_group_id=group.pk,
            defaults={
                "tenant": tenant,
                "name": group.name,
            },
        )


